add_shortcode( 'single_variations', 'perfectpixel_single_variations_shortcode' );

function perfectpixel_single_variations_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'limit' => 12, 'columns' => 4, 'category' => '' ), $atts );
	$args = array(
		'type'         => 'variation',
		'status'       => 'publish',
		'stock_status' => 'instock',
		'limit'        => min( 100, max( 1, absint( $atts['limit'] ) ) ),
	);
	if ( $atts['category'] ) {
		$parents        = wc_get_products( array( 'type' => 'variable', 'category' => array( sanitize_title( $atts['category'] ) ), 'limit' => -1, 'return' => 'ids' ) );
		$args['parent'] = $parents ? $parents : array( 0 );
	}
	$variations = array_filter( wc_get_products( $args ), function ( $v ) {
		return $v->is_purchasable() && $v->variation_is_visible();
	} );
	if ( ! $variations ) {
		return '';
	}
	$columns = min( 6, max( 1, absint( $atts['columns'] ) ) );
	$html    = '<div class="woocommerce columns-' . $columns . '"><ul class="products columns-' . $columns . '">';
	foreach ( $variations as $variation ) {
		$html .= sprintf(
			'<li class="product"><a href="%1$s">%2$s<h2 class="woocommerce-loop-product__title">%3$s</h2></a><span class="price">%4$s</span><a href="%5$s" class="button add_to_cart_button" rel="nofollow">%6$s</a></li>',
			esc_url( $variation->get_permalink() ),
			$variation->get_image( 'woocommerce_thumbnail' ),
			esc_html( $variation->get_name() ),
			wp_kses_post( $variation->get_price_html() ),
			esc_url( $variation->add_to_cart_url() ),
			esc_html( $variation->add_to_cart_text() )
		);
	}
	return $html . '</ul></div>';
}
